mapper.select:
SELECT DISTINCT n.* FROM novel n LEFT JOIN novel_category_relation ncr ON n.id= ncr.novel_id WHERE n.is_hot = 1 AND n.is_del = 0
AND ncr.category_id= #{categoryId}
ORDER BY n.update_time DESC LIMIT #{offset}, #{pageSize}

SELECT *
FROM novel
WHERE author_id = #{authorId}
AND is_del = 0
ORDER BY update_time DESC
LIMIT #{offset}, #{pageSize}
